function mirrorOffset(size,off){
  if(size<=0)return null;
  if(off<size)return off;
  // Espelhamento de ROM no mesmo modelo usado por Snes9x/bsnes.
  // Isto importa especialmente para cartuchos de tamanho nao potencia de dois.
  let mask=0x80000000;
  while(mask && !(off&mask))mask>>>=1;
  if(!mask)return 0;
  if(size<=(off&mask))return mirrorOffset(size,off-mask);
  return mask+mirrorOffset(size-mask,off-mask);
}
function snesToRomLegacy(rom,a){
  const bank=(a>>>16)&0xFF, addr=a&0xFFFF; let off;
  if(bank===0x7E||bank===0x7F)return null;
  switch(rom.header.mapping){
    case MAP.LOROM:{
      const lowMirror=(bank>=0x40&&bank<=0x7D)||(bank>=0xC0);
      if(addr<0x8000&&!lowMirror)return null;
      off=((bank&0x7F)<<15)|(addr&0x7FFF);
      break;
    }
    case MAP.HIROM:{
      const full=(bank>=0x40&&bank<=0x7D)||(bank>=0xC0);
      if(addr<0x8000&&!full)return null;
      off=((bank&0x3F)<<16)|addr; break;
    }
    case MAP.EXHIROM:{
      const full=(bank>=0x40&&bank<=0x7D)||(bank>=0xC0);
      if(addr<0x8000&&!full)return null;
      off=((bank&0x7F)<<16)|addr; if((bank&0x40)===0)off+=0x400000; break;
    }
    default:return null;
  }
  return mirrorOffset(rom.data.length,off);
}
// REV194: mapas base conferidos com bsnes boards.bml (LOROM, HIROM, EXLOROM, EXHIROM, SA1, SDD1, GSU) e com
// Snes9x memmap.cpp (Map_ExtendedHiROMMap). Regioes sem chip ficam sem ROM (barramento aberto no runtime).
function snesToRom(rom,a){
  const h=rom.header;if(h.mappingProfile==='legacy')return snesToRomLegacy(rom,a);
  const bank=(a>>>16)&0xFF, addr=a&0xFFFF; let off;
  if(bank===0x7E||bank===0x7F)return null;
  const io=bank<0x40||(bank>=0x80&&bank<0xC0);
  if(h.board==='SA1'||h.board==='SDD1'){
    if(io){if(addr<0x8000)return null;off=((bank&0x3F)<<15)|(addr&0x7FFF);if(h.board==='SA1'&&(bank&0x80))off+=0x200000;}
    else if(bank>=0xC0)off=((bank&0x3F)<<16)|addr;else return null;
    return mirrorOffset(rom.data.length,off);
  }
  if(h.board==='SPC7110'){
    // estado de reset da MMC: $4830-$4833 = 0,0,1,2 e $4834 = 0 (DROM de 1 MiB); PROM = 1o MiB
    if(!(bank>=0xC0||(io&&addr>=0x8000)))return null;
    const x=((bank&0x3F)<<16)|addr,region=(x>>>20)&3;
    if(region===0)return mirrorOffset(Math.min(0x100000,rom.data.length),x&0xFFFFF);
    const dsize=rom.data.length-0x100000;if(dsize<=0)return null;
    return 0x100000+mirrorOffset(dsize,(((x&0xFFFFF)|(0x100000*[0,0,1,2][region]))&0xFFFFF));
  }
  if(h.board==='BSLO'){
    if(!io||addr<0x8000)return null;
    off=(((bank&0x1F)<<15)|(addr&0x7FFF))+[0,0x100000,0x200000,0x100000][((bank>>>5)&1)|((bank>>>6)&2)];
    return mirrorOffset(rom.data.length,off);
  }
  if(h.board==='BSHI'){
    const lo=(bank<=0x1F||(bank>=0x80&&bank<=0x9F))&&addr>=0x8000,hi=(bank>=0x40&&bank<=0x5F)||(bank>=0xC0&&bank<=0xDF);
    if(!lo&&!hi)return null;return mirrorOffset(rom.data.length,((bank&0x1F)<<16)|addr);
  }
  if(h.board==='OBC1'){
    if(!io||addr<0x8000)return null;return mirrorOffset(rom.data.length,((bank&0x7F)<<15)|(addr&0x7FFF));
  }
  if(h.board==='ST018'||h.board==='SGB'){
    // ARM-LOROM-RAM e GB-LOROM espelham a ROM na metade baixa (ST018: $40-$6F/$C0-$EF; SGB: $40-$7D/$C0-$FF)
    const lowMirror=h.board==='ST018'?((bank>=0x40&&bank<=0x6F)||(bank>=0xC0&&bank<=0xEF)):((bank>=0x40&&bank<=0x7D)||bank>=0xC0);
    if(addr<0x8000&&!lowMirror)return null;return mirrorOffset(rom.data.length,((bank&0x7F)<<15)|(addr&0x7FFF));
  }
  if(h.board==='GSU'){
    if(io){if(addr<0x8000)return null;off=((bank&0x3F)<<15)|(addr&0x7FFF);}
    else if((bank>=0x40&&bank<=0x5F)||(bank>=0xC0&&bank<=0xDF))off=((bank&0x1F)<<16)|addr;else return null;
    return mirrorOffset(rom.data.length,off);
  }
  switch(h.mapping){
    case MAP.LOROM:
      if(addr<0x8000)return null;
      off=((bank&0x7F)<<15)|(addr&0x7FFF);break;
    case MAP.EXLOROM:
      if(addr<0x8000)return null;
      off=((bank&0x7F)<<15)|(addr&0x7FFF);if(bank<0x80)off+=0x400000;break;
    case MAP.HIROM:
      if(addr<0x8000&&io)return null;
      off=((bank&0x3F)<<16)|addr;break;
    case MAP.EXHIROM:
      if(addr<0x8000&&io)return null;
      off=((bank&0x3F)<<16)|addr;if(bank<0x80)off+=0x400000;break;
    default:return null;
  }
  return mirrorOffset(rom.data.length,off);
}
function cppMapperKind(h){const m=h.mapping,b=h.board;if(b==='SA1')return 'MapperKind::SA1';if(b==='SDD1')return 'MapperKind::SDD1';if(b==='GSU')return 'MapperKind::GSU';
  const extra={SPC7110:'SPC7110',OBC1:'OBC1',ST01X:'EXNEC',ST018:'ARM',BSLO:'BSLoROM',BSHI:'BSHiROM',SGB:'SGB'};if(extra[b])return 'MapperKind::'+extra[b];
  return m===MAP.HIROM?'MapperKind::HiROM':m===MAP.EXHIROM?'MapperKind::ExHiROM':m===MAP.EXLOROM?'MapperKind::ExLoROM':'MapperKind::LoROM';}
function isRomAddress(rom,a){return snesToRom(rom,a)!==null;}
function resetAddress(rom){return rom.header.resetVector&0xFFFF;}


