  body='for(;;){\n    if(forjaDepth.nested&&forja65_unwind_retired_enabled()&&!(hw.nativeReturns.size()>=forjaEntryFrames&&hw.nativeReturns[forjaEntryFrames-1].callToken==forjaEntryToken)){++gForja65RetiredUnwinds;hw.requestDispatch(cur,src);return;}\n'+body.slice('for(;;){'.length);
  body=body.replace(/if\(!hw\.dispatchPending(&&!continueInternalReturn\(\))?\)return;/g,m=>'forja65_resume_orphan_return(hw);'+m);
