  const hostDoc='FORJA65 '+VERSION+' - HOST NATIVO\n\nA fundacao Win32 foi reforcada com ideias reutilizaveis do port DKC3 Native PC v0.7.0.1:\n- XInput + teclado no host Windows.\n- pacing de apresentacao por steady_clock em 60 Hz/50 Hz conforme regiao, sem Sleep(16) fixo.\n- FORJA65_HEADLESS=1 impede abertura da janela para diagnosticos automatizados.\n- runtime_smoke + CTest validam carregamento do cart-data, framebuffer e inicializacao do runtime antes de executar o codigo convertido.\n- BUILD-WINDOWS.cmd e RUN-WINDOWS.cmd acompanham cada projeto gerado.\n- CMake copia assets tambem para a pasta final do executavel em builds multi-config (ex.: Release).\n- Falhas do game gravam forja65-last-error.txt e, no Windows, exibem MessageBox para o erro nao desaparecer.\n- Captura de cena PPU deterministica exporta VRAM/CGRAM/OAM, NPAL/NTIL/NMAP/NSCENE, camada OAM em NSPR, preview PPM e hashes de integridade.\n- A captura registra hash da ROM e do framebuffer para impedir mistura silenciosa de assets entre ROMs/capturas.\n- Oracle runtime registra FLOW/STATE/STACK dinamicos em forja65-oracle-hints.txt sem duplicatas e mantem forja65-oracle-observations.log com contexto de execucao.\n- Hints FLOW vindos de JMP/JSR (abs,X) podem expandir automaticamente vizinhos plausiveis da mesma tabela ROM.\n- RUN-ORACLE.cmd executa headless ate encontrar novo conhecimento ou completar o limite escolhido.\n- Oracle/hints agora carregam rom=<FNV1a64>; conhecimento de outra ROM/revisao e rejeitado pela analise.\n- Replay deterministico: FORJA65_INPUT_RECORD grava joypads por frame e FORJA65_INPUT_REPLAY reproduz exatamente o trace.\n- FORJA65_FRAME_HASHES=1 grava framebuffer/WRAM/PC por frame para comparar replays.\n- BUILD-QUALITY-WINDOWS.cmd ativa warnings-as-errors e sanitizers quando suportados pelo compilador.\n- equivalence_runner valida vetores de equivalencia produzidos por um oracle 65C816 de teste; ele nunca entra no game final.\n\nFORJA65_CAPTURE_FRAMES=1,60,120 salva varias cenas em uma execucao em frame-N/. Use RUN-CAPTURE-TIMELINE.cmd. FORJA65_CAPTURE_FRAME=N captura ao concluir o frame N. FORJA65_CAPTURE_DIR escolhe a pasta e FORJA65_CAPTURE_NAME o nome da cena. FORJA65_CAPTURE_STOP=1 encerra logo apos a captura.\nFORJA65_UNCAPPED=1 desativa o limitador de apresentacao.\nFORJA65_HEADLESS_FRAMES=N encerra teste headless depois de N frames.\n';
  const nativeAuditCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=600\r\nset FORJA65_NATIVE_AUDIT=1\r\nif exist forja65-native-dependency.csv del /q forja65-native-dependency.csv\r\nif exist forja65-native-dependency-report.txt del /q forja65-native-dependency-report.txt\r\ncall RUN-WINDOWS.cmd\r\necho.\r\necho Auditoria: forja65-native-dependency.csv e forja65-native-dependency-report.txt\r\npause\r\n';
  const migrationCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_PPU_MODE=state\r\nset FORJA65_DMA_MODE=native\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_ROM_MODE=hybrid\r\nset FORJA65_NATIVE_AUDIT=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=600\r\ncall RUN-WINDOWS.cmd\r\necho.\r\necho Veja forja65-native-dependency-report.txt\r\npause\r\n';
  const romProfileCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_ROM_MODE=cart\r\nset FORJA65_ROM_PROFILE=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=1200\r\nif exist forja65-rom-read-ranges.txt del /q forja65-rom-read-ranges.txt\r\ncall RUN-WINDOWS.cmd\r\necho Perfil: forja65-rom-read-ranges.txt\r\npause\r\n';
  const romPackCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nif not exist forja65-rom-read-ranges.txt (echo Rode RUN-ROM-PROFILE.cmd primeiro.& pause & exit /b 2)\r\nset TOOL=build\\Release\\rom_pack_builder.exe\r\nif not exist "%TOOL%" set TOOL=build\\rom_pack_builder.exe\r\nif not exist "%TOOL%" (echo Compile primeiro com BUILD-WINDOWS.cmd.& pause & exit /b 3)\r\n"%TOOL%" assets\\cart-data.bin forja65-rom-read-ranges.txt assets\\native-rom-data.bin\r\nif errorlevel 1 (pause & exit /b 4)\r\necho Criado assets\\native-rom-data.bin\r\npause\r\n';
  const romNativeCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nif not exist assets\\native-rom-data.bin (echo Crie o pack com BUILD-NATIVE-ROM-PACK.cmd.& pause & exit /b 2)\r\nset FORJA65_ROM_MODE=native\r\nset FORJA65_PPU_MODE=state\r\nset FORJA65_DMA_MODE=native\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_NATIVE_AUDIT=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=600\r\ncall RUN-WINDOWS.cmd\r\npause\r\n';
  const captureSpcCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FRAME=%~1\r\nif "%FRAME%"=="" set FRAME=300\r\nset /a LIMIT=FRAME+2\r\nset FORJA65_CAPTURE_SPC_FRAME=%FRAME%\r\nset FORJA65_CAPTURE_SPC_STOP=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%LIMIT%\r\ncall RUN-WINDOWS.cmd\r\necho Captura: forja65-spc-capture\\spc-ram.bin + spc-capture.txt\r\npause\r\n';
  const nativeCutoverCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_PPU_MODE=state\r\nset FORJA65_DMA_MODE=native\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_ROM_MODE=hybrid\r\nset FORJA65_NATIVE_AUDIT=1\r\nset FORJA65_AUDIO_DUMP=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=1200\r\nif exist forja65-native-dependency.csv del /q forja65-native-dependency.csv\r\nif exist forja65-native-dependency-report.txt del /q forja65-native-dependency-report.txt\r\ncall RUN-WINDOWS.cmd\r\necho.\r\necho CUTOVER concluido. Verifique PPU_VIRTUAL_HW, APU_VIRTUAL_HW, DSP_VIRTUAL_HW, DMA fallback e ROM fallback no relatorio.\r\npause\r\n';
  const nativeAudioCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_AUDIO_DUMP=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=600\r\ncall RUN-WINDOWS.cmd\r\necho Audio PCM: forja65-native-audio.wav\r\npause\r\n';
  const romConvergeCmd='@echo off\r\nsetlocal EnableExtensions\r\ncd /d "%~dp0"\r\nset FRAMES=%~1\r\nif "%FRAMES%"=="" set FRAMES=1200\r\nset GAME=bin\\game.exe\r\nif not exist "%GAME%" set GAME=build-win\\Release\\game.exe\r\nif not exist "%GAME%" (echo Execute BUILD-WINDOWS.cmd primeiro.& pause & exit /b 2)\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%FRAMES%\r\nset FORJA65_ROM_MODE=cart\r\nset FORJA65_ROM_PROFILE=1\r\nif exist forja65-rom-read-ranges.txt del /q forja65-rom-read-ranges.txt\r\n"%GAME%" || (echo Falha durante profile.& pause & exit /b 3)\r\nset TOOL=build-win\\Release\\rom_pack_builder.exe\r\nif not exist "%TOOL%" set TOOL=build\\Release\\rom_pack_builder.exe\r\nif not exist "%TOOL%" set TOOL=build\\rom_pack_builder.exe\r\nif not exist "%TOOL%" (echo rom_pack_builder nao encontrado. Recompile.& pause & exit /b 4)\r\n"%TOOL%" assets\\cart-data.bin forja65-rom-read-ranges.txt assets\\native-rom-data.bin || (pause & exit /b 5)\r\nset FORJA65_ROM_PROFILE=\r\nset FORJA65_ROM_MODE=native\r\nset FORJA65_PPU_MODE=state\r\nset FORJA65_DMA_MODE=native\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_NATIVE_AUDIT=1\r\n"%GAME%" || (echo Pack ainda incompleto. Veja forja65-native-rom-missing.txt.& pause & exit /b 6)\r\necho ROM convergence PASS para %FRAMES% frames.\r\npause\r\n';
  const nativePortRunCmd='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_ROM_MODE=native\r\nset FORJA65_PPU_MODE=state\r\nset FORJA65_DMA_MODE=native\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_AUDIO_DUMP=0\r\ngame.exe\r\nexit /b %ERRORLEVEL%\r\n';
