  const gameplayQaScript="#!/usr/bin/env python3\n\"\"\"Compare two deterministic Forja65 scene timelines (standard-library only).\n\nThis is a *visual-state* regression test, not an emulator accuracy oracle.\n\"\"\"\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\nimport sys\n\n\ndef read_ppm(path):\n    # Our scene exporter writes P6 RGB; reject malformed and truncated captures.\n    data = path.read_bytes()\n    if not data.startswith(b'P6\\n'):\n        raise ValueError(f'{path}: expected binary P6 PPM')\n    offset = 3\n    tokens = []\n    while len(tokens) < 3:\n        while offset < len(data) and data[offset] in b' \\t\\r\\n':\n            offset += 1\n        if offset < len(data) and data[offset] == 35:  # # comment\n            while offset < len(data) and data[offset] != 10:\n                offset += 1\n            continue\n        end = offset\n        while end < len(data) and data[end] not in b' \\t\\r\\n':\n            end += 1\n        if end == offset:\n            raise ValueError(f'{path}: missing image dimension')\n        tokens.append(int(data[offset:end]))\n        offset = end\n    width, height, max_value = tokens\n    if width <= 0 or height <= 0 or width > 8192 or height > 8192 or max_value != 255:\n        raise ValueError(f'{path}: unsupported PPM dimensions or max sample')\n    if offset >= len(data) or data[offset] not in b' \\t\\r\\n':\n        raise ValueError(f'{path}: bad raster separator')\n    if data[offset:offset+2] == b'\\r\\n':\n        offset += 2\n    else:\n        offset += 1\n    rgb = data[offset:]\n    if len(rgb) != width * height * 3:\n        raise ValueError(f'{path}: wrong RGB byte count {len(rgb)}')\n    return width, height, rgb\n\n\ndef compare(a, b):\n    ia, ib = read_ppm(a), read_ppm(b)\n    if ia[:2] != ib[:2]:\n        raise ValueError(f'frame size mismatch {a} / {b}')\n    xa, xb = ia[2], ib[2]\n    delta = sum(xa[i:i+3] != xb[i:i+3] for i in range(0, len(xa), 3))\n    return {'different_pixels': delta, 'total_pixels': ia[0]*ia[1],\n            'first_sha256': hashlib.sha256(xa).hexdigest(),\n            'second_sha256': hashlib.sha256(xb).hexdigest()}\n\n\ndef evaluate(base, variant, rules):\n    results = []\n    allowed = {'same_across', 'different_across', 'frozen_variant', 'changed_variant'}\n    for rule in rules:\n        action = rule['type']\n        frames = rule['frames']\n        if action not in allowed or not isinstance(frames, list) or not frames:\n            raise ValueError('invalid rule type or frames')\n        if action in ('frozen_variant', 'changed_variant') and len(frames) != 2:\n            raise ValueError(f'{action} requires exactly two frames')\n        if any(not isinstance(n, int) or isinstance(n, bool) or n <= 0 for n in frames):\n            raise ValueError('frames must be positive integers')\n        comparisons = []\n        if action.endswith('_across'):\n            pairs = [(base / f'frame-{n}' / 'preview.ppm',\n                      variant / f'frame-{n}' / 'preview.ppm') for n in frames]\n        else:\n            pairs = [(variant / f'frame-{frames[0]}' / 'preview.ppm',\n                      variant / f'frame-{frames[1]}' / 'preview.ppm')]\n        for a, b in pairs:\n            comparisons.append(compare(a, b))\n        expected_same = action in ('same_across', 'frozen_variant')\n        passed = all((entry['different_pixels'] == 0) == expected_same for entry in comparisons)\n        results.append({'type': action, 'frames': frames, 'pass': passed,\n                        'compared_pixels': [p['different_pixels'] for p in comparisons]})\n    return {'pass': all(x['pass'] for x in results), 'rules': results,\n            'warning': 'Visual regression only; not proof of SNES hardware equivalence or game completion'}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--baseline', required=True, type=Path)\n    parser.add_argument('--variant', required=True, type=Path)\n    parser.add_argument('--rules', required=True, type=Path, help='JSON list of assertions')\n    parser.add_argument('--report', type=Path)\n    args = parser.parse_args()\n    try:\n        rules = json.loads(args.rules.read_text(encoding='utf-8'))\n        report = evaluate(args.baseline, args.variant, rules)\n        if args.report:\n            args.report.parent.mkdir(parents=True, exist_ok=True)\n            args.report.write_text(json.dumps(report, indent=2) + '\\n', encoding='utf-8')\n        for entry in report['rules']:\n            print(('PASS' if entry['pass'] else 'FAIL'), entry['type'], entry['frames'], entry['compared_pixels'])\n        return 0 if report['pass'] else 1\n    except (ValueError, OSError, KeyError, TypeError, json.JSONDecodeError) as exc:\n        print('GAMEPLAY_QA_ERROR:', exc, file=sys.stderr)\n        return 2\n\n\nif __name__ == '__main__':\n    sys.exit(main())\n";
  const gameplayControlsQaScript="#!/usr/bin/env python3\n\"\"\"Forja65 deterministic gameplay input A/B validator (stdlib only).\n\nRuns a baseline and four isolated input pulses, comparing actual PPU captures.\nThis checks observable visual response, not correctness against a SNES reference.\n\"\"\"\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport shutil\nimport subprocess\nimport sys\n\nBUTTONS = {'left': '0200', 'right': '0100', 'rotate': '0080', 'down': '0400'}\nCASES = ('baseline', *BUTTONS)\nEVENT = re.compile(r'^frame=(\\d+)\\s+joy1=([0-9a-fA-F]{4})\\s+joy2=([0-9a-fA-F]{4})$')\n\n\ndef read_ppm(path):\n    data = path.read_bytes()\n    if not data.startswith(b'P6\\n'):\n        raise ValueError(f'{path}: imagem PPM P6 invalida')\n    index, tokens = 3, []\n    while len(tokens) < 3:\n        while index < len(data) and data[index] in b' \\t\\r\\n':\n            index += 1\n        if index < len(data) and data[index] == 35:\n            while index < len(data) and data[index] != 10:\n                index += 1\n            continue\n        start = index\n        while index < len(data) and data[index] not in b' \\t\\r\\n':\n            index += 1\n        if start == index:\n            raise ValueError(f'{path}: header incompleto')\n        try:\n            tokens.append(int(data[start:index]))\n        except ValueError as exc:\n            raise ValueError(f'{path}: dimensoes invalidas') from exc\n    w, h, maximum = tokens\n    if not (0 < w <= 8192 and 0 < h <= 8192 and maximum == 255):\n        raise ValueError(f'{path}: tamanho/maximo invalido')\n    if index >= len(data) or data[index] not in b' \\t\\r\\n':\n        raise ValueError(f'{path}: sem separador RGB')\n    index += 2 if data[index:index+2] == b'\\r\\n' else 1\n    rgb = data[index:]\n    if len(rgb) != w*h*3:\n        raise ValueError(f'{path}: captura truncada: {len(rgb)} bytes RGB')\n    return w, h, rgb\n\n\ndef compare_images(a, b, roi):\n    w, h, ar = read_ppm(a)\n    bw, bh, br = read_ppm(b)\n    if (w,h)!=(bw,bh):\n        raise ValueError('imagens possuem tamanhos diferentes')\n    x0,y0,x1,y1=roi\n    if not (0<=x0<x1<=w and 0<=y0<y1<=h):\n        raise ValueError(f'ROI {roi} fora da imagem {w}x{h}')\n    inside = outside = 0\n    for p in range(w*h):\n        k = p*3\n        if ar[k:k+3] != br[k:k+3]:\n            x,y=p%w,p//w\n            if x0 <= x < x1 and y0 <= y < y1:\n                inside+=1\n            else:\n                outside+=1\n    return {'within_piece_roi':inside,'outside_piece_roi':outside,\n            'different_pixels':inside+outside}\n\n\ndef capture(root, name, frame):\n    return root/name/'captures'/f'frame-{frame}'/'preview.ppm'\n\n\ndef validate(root, before=1834, after=(1843, 1850, 1860), roi=(104,40,160,128), min_pixels=64):\n    root=Path(root)\n    results={}\n    # Branches must share the exact same state BEFORE the isolated button event.\n    for name in BUTTONS:\n        m=compare_images(capture(root,'baseline',before),capture(root,name,before),roi)\n        if m['different_pixels']:\n            raise ValueError(f'{name}: divergencia ANTES do comando no quadro {before}: {m}')\n        comparisons=[]\n        for frame in after:\n            m=compare_images(capture(root,'baseline',frame),capture(root,name,frame),roi)\n            comparisons.append({'frame':frame,**m})\n            if m['within_piece_roi'] < min_pixels:\n                raise ValueError(f'{name}: sem resposta suficiente da peca no quadro {frame}: {m}')\n            if m['outside_piece_roi']:\n                raise ValueError(f'{name}: alteracao fora da regiao da peca no quadro {frame}: {m}')\n        results[name]={'before_identical':True,'after':comparisons}\n    # Opposite directions and other actions should not collapse to the same frame.\n    for left,right in (('left','right'),('left','rotate'),('rotate','down'),('right','down')):\n        m=compare_images(capture(root,left,after[0]),capture(root,right,after[0]),roi)\n        if m['within_piece_roi'] < min_pixels:\n            raise ValueError(f'{left}/{right} produziram imagens indistinguiveis')\n    return {'pass':True,'before_frame':before,'after_frames':list(after),'piece_roi':list(roi),\n            'cases':results,'note':'A/B de controles e framebuffer; nao prova colisoes ou fidelidade ao SNES original'}\n\n\ndef load_input_schedule(path):\n    events={}\n    for lineno,line in enumerate(path.read_text(encoding='utf-8-sig').splitlines(),1):\n        line=line.split('#',1)[0].strip()\n        if not line:\n            continue\n        m=EVENT.fullmatch(line)\n        if not m:\n            raise ValueError(f'{path}:{lineno}: linha de entrada invalida')\n        frame=int(m.group(1))\n        if frame in events:\n            raise ValueError(f'{path}:{lineno}: quadro duplicado {frame}')\n        events[frame]=(m.group(2).lower(),m.group(3).lower())\n    if 0 not in events:\n        raise ValueError('replay nao contem quadro 0')\n    return events\n\n\ndef build_trace(events, pulse, hold, button):\n    events=events.copy()\n    if button is not None:\n        if any(f in events for f in (pulse,pulse+hold)):\n            raise ValueError('pulso coincide com um evento do replay original')\n        # Do not silently change existing controller state.\n        previous=[f for f in events if f < pulse]\n        if not previous or events[max(previous)] != ('0000','0000'):\n            raise ValueError('pulso exige controles liberados antes do evento')\n        events[pulse]=(button,'0000')\n        events[pulse+hold]=('0000','0000')\n    return '# Replay gerado para teste A/B do Forja65\\n'+'\\n'.join(\n        f'frame={f} joy1={v[0]} joy2={v[1]}' for f,v in sorted(events.items()))+'\\n'\n\n\ndef run_cases(game, cart, trace, output, pulse, hold, frames):\n    events=load_input_schedule(trace)\n    game,cart=Path(game).resolve(),Path(cart).resolve()\n    if not game.is_file() or not cart.is_file():\n        raise FileNotFoundError('game ou assets/cart-data.bin ausente; compile primeiro')\n    if min(frames)<=0 or max(frames)<=pulse+hold:\n        raise ValueError('capturas precisam ocorrer depois do pulso e sua liberacao')\n    # Captures are intentionally independent; each uses identical runtime settings.\n    for name in CASES:\n        folder=output/name\n        (folder/'assets').mkdir(parents=True,exist_ok=True)\n        shutil.copy2(cart,folder/'assets'/'cart-data.bin')\n        (folder/'input.txt').write_text(build_trace(events,pulse,hold,BUTTONS.get(name)),encoding='utf-8')\n        captures=folder/'captures'\n        if captures.exists():\n            shutil.rmtree(captures)\n        env=os.environ.copy()\n        env.update(FORJA65_HEADLESS='1',FORJA65_UNCAPPED='1',FORJA65_CAPTURE_STOP='1',\n                   FORJA65_HEADLESS_FRAMES=str(max(frames)),FORJA65_CAPTURE_FRAMES=','.join(map(str,frames)),\n                   FORJA65_CAPTURE_DIR=str(captures.resolve()),FORJA65_INPUT_REPLAY=str((folder/'input.txt').resolve()))\n        # Avoid inherited debug/experimental overrides from other launches.\n        for key in list(env):\n            if key.startswith('FORJA65_SPC_') or key in ('FORJA65_FRAME_HASHES','FORJA65_INPUT_RECORD'):\n                env.pop(key,None)\n        with (folder/'run.log').open('w',encoding='utf-8') as log:\n            finished=subprocess.run([str(game)],cwd=folder,env=env,stdout=log,stderr=subprocess.STDOUT)\n        if finished.returncode:\n            raise RuntimeError(f'{name}: jogo terminou com erro {finished.returncode}, veja {folder / \"run.log\"}')\n        for frame in frames:\n            if not capture(output,name,frame).is_file():\n                raise RuntimeError(f'{name}: faltou captura do quadro {frame}')\n        qa=folder/'forja65-qa-status.txt'\n        if not qa.is_file() or 'runtime_started=PASS' not in qa.read_text():\n            raise RuntimeError(f'{name}: runtime nao confirmou inicializacao')\n        print(f'CAPTURA_OK {name} {max(frames)} quadros',flush=True)\n\n\ndef main():\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument('--output',type=Path,required=True)\n    parser.add_argument('--game',type=Path,help='executavel C++ opcional; sem ele valida capturas existentes')\n    parser.add_argument('--cart',type=Path)\n    parser.add_argument('--trace',type=Path)\n    parser.add_argument('--pulse',type=int,default=1835)\n    parser.add_argument('--hold',type=int,default=6)\n    parser.add_argument('--before',type=int,default=1834)\n    parser.add_argument('--after',default='1843,1850,1860')\n    parser.add_argument('--roi',default='104,40,160,128')\n    parser.add_argument('--report',type=Path)\n    args=parser.parse_args()\n    try:\n        after=tuple(int(v) for v in args.after.split(','))\n        roi=tuple(int(v) for v in args.roi.split(','))\n        if len(after)<1 or len(roi)!=4 or args.before>=args.pulse or args.pulse+args.hold>=min(after):\n            raise ValueError('parametros de quadros/ROI invalidos')\n        if args.game:\n            if not args.cart or not args.trace:\n                raise ValueError('--game requer --cart e --trace')\n            run_cases(args.game,args.cart,args.trace,args.output,args.pulse,args.hold,\n                      sorted(set((args.before,*after))))\n        report=validate(args.output,args.before,after,roi)\n        report_file=args.report or args.output/'resultado-controles.json'\n        report_file.parent.mkdir(parents=True,exist_ok=True)\n        report_file.write_text(json.dumps(report,indent=2)+'\\n',encoding='utf-8')\n        for name,r in report['cases'].items():\n            print('CONTROLE_OK',name,[(i['frame'],i['within_piece_roi']) for i in r['after']])\n        print('QA_CONTROLES_PASS')\n        return 0\n    except (OSError,ValueError,RuntimeError) as exc:\n        print('QA_CONTROLES_FAIL:',exc,file=sys.stderr)\n        return 2\n\n\nif __name__=='__main__':\n    raise SystemExit(main())\n";
  // v0.4.17: standalone OAM collision/lock QA utilities. Caller must supply
  // game-specific piece signatures and capture frame windows.
  const gameplayWallQaScript="#!/usr/bin/env python3\n\"\"\"Deterministic OAM wall-collision regression; portable across Forja65 ports.\n\nVerifies a *specific* piece with a stable tile signature reaches its expected\nleft/right horizontal bounds, never crosses them, and continues moving vertically.\nDoes not prove collisions with stacked tiles or line clear behavior.\n\"\"\"\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport shutil\nimport subprocess\nimport sys\n\nSPRITE_RE = re.compile(r'^slot=(\\d+) x=(-?\\d+) y=(-?\\d+) size=(\\d+) tile=(\\d+) attr=([0-9a-fA-F]+) hflip=([01]) vflip=([01])$')\nINPUT_RE = re.compile(r'^frame=(\\d+) joy1=([0-9a-fA-F]{4}) joy2=([0-9a-fA-F]{4})$')\nBUTTONS = {'hold_left': '0200', 'hold_right': '0100'}\n\n\ndef read_piece(path, tiles, x_range=(80, 180), y_range=(32, 175)):\n    content = path.read_text(encoding='utf-8')\n    if not content.startswith('FORJA65_OAM_SPRITES 1\\n'):\n        raise ValueError(f'{path}: OAM header invalido')\n    found = {}\n    for line in content.splitlines()[1:]:\n        if line.startswith('obsel=') or line.startswith('visible_slots='):\n            continue\n        m = SPRITE_RE.fullmatch(line)\n        if m is None:\n            raise ValueError(f'{path}: linha OAM invalida: {line[:100]}')\n        slot,x,y,size,tile,attr,hflip,vflip = m.groups()\n        x,y,size,tile=int(x),int(y),int(size),int(tile)\n        if (tile in tiles and size==8 and x_range[0]<=x<x_range[1]\n                and y_range[0]<=y<y_range[1]):\n            if tile in found:\n                raise ValueError(f'{path}: tile de peca duplicado: {tile}')\n            found[tile] = (x, y)\n    if set(found) != set(tiles):\n        raise ValueError(f'{path}: peca incompleta, encontrados={sorted(found)}, esperados={sorted(tiles)}')\n    min_x=min(x for x,y in found.values())\n    min_y=min(y for x,y in found.values())\n    shape=tuple((t,found[t][0]-min_x,found[t][1]-min_y) for t in tiles)\n    return {'x':min_x,'y':min_y,'shape':shape}\n\n\ndef parse_trace(trace):\n    events={}\n    for n,line in enumerate(trace.read_text(encoding='utf-8-sig').splitlines(),1):\n        line=line.split('#',1)[0].strip()\n        if not line:\n            continue\n        m=INPUT_RE.fullmatch(line)\n        if not m: raise ValueError(f'{trace}:{n}: linha invalida')\n        frame=int(m.group(1))\n        if frame in events:raise ValueError(f'{trace}:{n}: quadro duplicado')\n        events[frame]=(m.group(2).lower(),m.group(3).lower())\n    if 0 not in events: raise ValueError('replay sem quadro zero')\n    return events\n\n\ndef create_trace(trace, start, stop, button):\n    events=parse_trace(trace)\n    if not (0<start<stop):raise ValueError('intervalo de controle invalido')\n    if any(start <= f <= stop for f in events):\n        raise ValueError('controle sustentado sobrepoe comando existente')\n    prev=max(f for f in events if f<start)\n    if events[prev] != ('0000','0000'):\n        raise ValueError('botao anterior nao foi liberado')\n    events[start]=(button,'0000')\n    events[stop]=('0000','0000')\n    return '# Wall QA generated deterministic input\\n'+'\\n'.join(\n        f'frame={f} joy1={v[0]} joy2={v[1]}' for f,v in sorted(events.items()))+'\\n'\n\n\ndef run_cases(game,cart,trace,output,frames,start,stop):\n    game,cart,trace=Path(game).resolve(),Path(cart).resolve(),Path(trace).resolve()\n    if not (game.is_file() and cart.is_file() and trace.is_file()):\n        raise FileNotFoundError('game, cart ou replay nao encontrado')\n    if min(frames)>=start or max(frames)<=stop:\n        raise ValueError('capturas devem incluir antes do controle e apos sua liberacao')\n    for name,button in BUTTONS.items():\n        d=output/name\n        (d/'assets').mkdir(parents=True,exist_ok=True)\n        shutil.copy2(cart,d/'assets'/'cart-data.bin')\n        (d/'input.txt').write_text(create_trace(trace,start,stop,button),encoding='utf-8')\n        captures=d/'captures'\n        if captures.exists():shutil.rmtree(captures)\n        env=os.environ.copy()\n        for key in list(env):\n            if key.startswith('FORJA65_SPC_') or key in ('FORJA65_FRAME_HASHES','FORJA65_INPUT_RECORD'):\n                env.pop(key,None)\n        env.update(FORJA65_HEADLESS='1', FORJA65_UNCAPPED='1', FORJA65_CAPTURE_STOP='1',\n                   FORJA65_HEADLESS_FRAMES=str(max(frames)),\n                   FORJA65_CAPTURE_FRAMES=','.join(map(str,frames)),\n                   FORJA65_CAPTURE_DIR=str(captures.resolve()),\n                   FORJA65_INPUT_REPLAY=str((d/'input.txt').resolve()))\n        with (d/'run.log').open('w',encoding='utf-8') as log:\n            result=subprocess.run([str(game)],cwd=d,env=env,stdout=log,stderr=subprocess.STDOUT)\n        if result.returncode: raise RuntimeError(f'{name}: runtime error={result.returncode}; veja {d / \"run.log\"}')\n        for frame in frames:\n            if not (captures/f'frame-{frame}'/'oam-sprites.txt').is_file():\n                raise RuntimeError(f'{name}: captura OAM ausente no quadro {frame}')\n        qa=d/'forja65-qa-status.txt'\n        if not qa.exists() or 'runtime_started=PASS' not in qa.read_text():\n            raise RuntimeError(f'{name}: runtime nao confirmou inicializacao')\n        print('CAPTURE_PASS',name,max(frames),flush=True)\n\n\ndef validate(root, frames, tiles, expected_left, expected_right,\n             plateau_frames=(1875,1890,1905,1920,1935,1950,1970),\n             x_range=(80,180), y_range=(32,175)):\n    root=Path(root)\n    if not frames or sorted(set(frames))!=list(frames):\n        raise ValueError('quadros devem estar em ordem crescente sem repeticao')\n    if min(frames)>=min(plateau_frames) or not set(plateau_frames).issubset(frames):\n        raise ValueError('quadros de borda nao estao incluidos na captura')\n    if expected_left>=expected_right:raise ValueError('limites invertidos')\n    output={}\n    common_shape=None\n    for case,wall in (('hold_left',expected_left),('hold_right',expected_right)):\n        data=[]\n        for f in frames:\n            path=root/case/'captures'/f'frame-{f}'/'oam-sprites.txt'\n            piece=read_piece(path,tiles,x_range,y_range)\n            if common_shape is None: common_shape=piece['shape']\n            if piece['shape']!=common_shape:\n                raise ValueError(f'{case} frame {f}: outra peca ou rotacao detectada')\n            data.append({'frame':f,'x':piece['x'],'y':piece['y']})\n        if case=='hold_left' and any(p['x']<wall for p in data):\n            raise ValueError('peca atravessou a parede esquerda')\n        if case=='hold_right' and any(p['x']>wall for p in data):\n            raise ValueError('peca atravessou a parede direita')\n        plateau=[p for p in data if p['frame'] in plateau_frames]\n        if len(plateau)<4 or any(p['x']!=wall for p in plateau):\n            raise ValueError(f'{case}: colisao nao manteve limite esperado {wall}: {plateau}')\n        if case=='hold_left' and not (data[0]['x']>wall and any(p['x']<data[0]['x'] for p in data)):\n            raise ValueError('comando esquerda nao deslocou a peca')\n        if case=='hold_right' and not (data[0]['x']<wall and any(p['x']>data[0]['x'] for p in data)):\n            raise ValueError('comando direita nao deslocou a peca')\n        # Contact must not be disguised by a frozen or reset game.\n        ys=[p['y'] for p in plateau]\n        if any(b<a for a,b in zip(ys,ys[1:])) or len(set(ys))<3:\n            raise ValueError(f'{case}: gravidade nao progrediu apos contato com borda')\n        output[case]={'wall':wall,'first_x':data[0]['x'],\n                      'contact_frame':next(p['frame'] for p in data if p['x']==wall),\n                      'vertical_progress':ys[-1]-ys[0], 'positions':data}\n    if output['hold_left']['positions'][0]!=output['hold_right']['positions'][0]:\n        raise ValueError('as duas execucoes ja divergiam antes dos controles')\n    return {'pass':True, 'status':'colisao_lateral_observada', 'tile_signature':list(tiles),\n            'results':output,'limitations':'Nao valida empilhamento, limpeza de linhas nem equivalencia ao SNES.'}\n\n\ndef main():\n    ap=argparse.ArgumentParser(description=__doc__)\n    ap.add_argument('--output',type=Path,required=True)\n    ap.add_argument('--game',type=Path)\n    ap.add_argument('--cart',type=Path)\n    ap.add_argument('--trace',type=Path)\n    ap.add_argument('--frames',default='1834,1843,1860,1875,1890,1905,1920,1935,1950,1970')\n    ap.add_argument('--plateau-frames',default='1875,1890,1905,1920,1935,1950,1970')\n    ap.add_argument('--start',type=int,default=1835)\n    ap.add_argument('--stop',type=int,default=1960)\n    ap.add_argument('--tiles',default='2,3,11,5')\n    ap.add_argument('--left-wall',type=int,default=88)\n    ap.add_argument('--right-wall',type=int,default=144)\n    ap.add_argument('--report',type=Path)\n    args=ap.parse_args()\n    try:\n        frames=[int(x) for x in args.frames.split(',')]\n        plateau=[int(x) for x in args.plateau_frames.split(',')]\n        tiles=[int(x) for x in args.tiles.split(',')]\n        if len(tiles)<2 or len(tiles)!=len(set(tiles)) or not all(0<=t<=255 for t in tiles):\n            raise ValueError('assinatura de tiles invalida')\n        if args.game:\n            if not args.cart or not args.trace:raise ValueError('--game requer --cart e --trace')\n            run_cases(args.game,args.cart,args.trace,args.output,frames,args.start,args.stop)\n        result=validate(args.output,frames,tiles,args.left_wall,args.right_wall,plateau)\n        p=args.report or args.output/'resultado-paredes.json'\n        p.parent.mkdir(parents=True,exist_ok=True)\n        p.write_text(json.dumps(result,indent=2)+'\\n',encoding='utf-8')\n        print('WALL_COLLISION_PASS',result['results']['hold_left']['wall'],result['results']['hold_right']['wall'])\n        return 0\n    except (OSError,RuntimeError,ValueError) as exc:\n        print('WALL_COLLISION_FAIL',exc,file=sys.stderr)\n        return 2\n\nif __name__=='__main__':\n    sys.exit(main())\n";
  const gameplayLockQaScript="#!/usr/bin/env python3\n\"\"\"Observe a falling-piece handoff using OAM and PPU; not a line-clear oracle.\"\"\"\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport shutil\nimport subprocess\nimport sys\n\nOAM=re.compile(r'^slot=\\d+ x=(-?\\d+) y=(-?\\d+) size=(\\d+) tile=(\\d+) attr=[0-9a-fA-F]+ hflip=[01] vflip=[01]$')\nINPUT=re.compile(r'^frame=(\\d+) joy1=([0-9a-fA-F]{4}) joy2=([0-9a-fA-F]{4})$')\n\n\ndef piece_tiles(path, roi=(80,25,175,190)):\n    data=path.read_text(encoding='utf-8')\n    if not data.startswith('FORJA65_OAM_SPRITES 1\\n'):\n        raise ValueError('formato de OAM inesperado')\n    sprites=[]\n    for line in data.splitlines()[1:]:\n        if line.startswith(('obsel=','visible_slots=')):continue\n        m=OAM.fullmatch(line)\n        if not m: raise ValueError(f'linha de OAM invalida em {path}: {line}')\n        x,y,sz,t=map(int,m.groups())\n        if sz==8 and roi[0]<=x<roi[2] and roi[1]<=y<roi[3]:\n            sprites.append((x,y,t))\n    return sprites\n\n\ndef read_ppm(path):\n    data=path.read_bytes()\n    if not data.startswith(b'P6\\n'):raise ValueError('captura PPM P6 invalida')\n    m=re.match(rb'P6\\s+(\\d+)\\s+(\\d+)\\s+(\\d+)\\s',data)\n    if m is None: raise ValueError('cabecalho PPM invalido')\n    w,h,maxval=map(int,m.groups())\n    if not (0<w<=8192 and 0<h<=8192 and maxval==255):\n        raise ValueError('dimensoes PPM invalidas')\n    image=data[m.end():]\n    if len(image)!=w*h*3:raise ValueError('imagem PPM incompleta')\n    return (w,h,image)\n\n\ndef board_diff(a,b,roi):\n    w,h,pa=read_ppm(a)\n    bw,bh,pb=read_ppm(b)\n    if (w,h)!=(bw,bh):raise ValueError('dimensoes de captura mudaram')\n    x0,y0,x1,y1=roi\n    if not (0<=x0<x1<=w and 0<=y0<y1<=h):raise ValueError('regiao do tabuleiro invalida')\n    return sum(pa[(y*w+x)*3:(y*w+x)*3+3]!=pb[(y*w+x)*3:(y*w+x)*3+3]\n               for y in range(y0,y1) for x in range(x0,x1))\n\n\ndef validate(folder,frames=(1875,1900,1925),old_tiles=(2,3,11,5),new_tiles=(2,13,5,4),board=(88,32,170,200)):\n    folder=Path(folder)\n    if len(frames)!=3 or sorted(set(frames))!=list(frames):\n        raise ValueError('esperados 3 quadros crescentes')\n    dirs=[folder/'captures'/f'frame-{f}' for f in frames]\n    samples=[piece_tiles(d/'oam-sprites.txt') for d in dirs]\n    def signature(s):return sorted(t for x,y,t in s)\n    if signature(samples[0])!=sorted(old_tiles):\n        raise ValueError(f'primeira peca nao corresponde a assinatura: {samples[0]}')\n    if samples[1]:\n        raise ValueError(f'peca ainda ativa no quadro de transferencia: {samples[1]}')\n    if signature(samples[2])!=sorted(new_tiles) or sorted(old_tiles)==sorted(new_tiles):\n        raise ValueError(f'nova peca nao detectada: {samples[2]}')\n    # No visual disappearance when the old piece is removed from OAM.\n    dif=board_diff(dirs[0]/'preview.ppm',dirs[1]/'preview.ppm',board)\n    if dif:\n        raise ValueError(f'area do tabuleiro mudou no handoff: {dif} pixels')\n    new_y=min(y for x,y,t in samples[2])\n    old_y=max(y for x,y,t in samples[0])\n    if new_y>=old_y:\n        raise ValueError('nova peca nao apareceu proxima ao topo')\n    return {'pass':True,'status':'handoff_visual_observado','frames':list(frames),\n            'old_tiles':sorted(old_tiles),'new_tiles':sorted(new_tiles),\n            'preserved_pixels':(board[2]-board[0])*(board[3]-board[1]),\n            'new_piece_top_y':new_y,'old_piece_bottom_y':old_y,\n            'limitations':'Nao demonstra limpeza de linhas nem todas as colisoes com pilha.'}\n\n\ndef make_replay(path,start,stop):\n    events={}\n    for n,line in enumerate(path.read_text(encoding='utf-8-sig').splitlines(),1):\n        line=line.split('#',1)[0].strip()\n        if not line:continue\n        m=INPUT.fullmatch(line)\n        if not m:raise ValueError(f'{path}:{n}: entrada invalida')\n        frame=int(m.group(1))\n        if frame in events:raise ValueError('replay com quadro duplicado')\n        events[frame]=(m.group(2).lower(),m.group(3).lower())\n    if 0 not in events or not(0<start<stop) or any(start<=f<=stop for f in events):\n        raise ValueError('sequencia de comandos incompatível com descida sustentada')\n    prev=max(f for f in events if f<start)\n    if events[prev]!=('0000','0000'):raise ValueError('controle anterior ainda ativo')\n    events[start]=('0400','0000');events[stop]=('0000','0000')\n    return '# Soft-drop QA replay\\n'+'\\n'.join(f'frame={f} joy1={j1} joy2={j2}' for f,(j1,j2) in sorted(events.items()))+'\\n'\n\n\ndef run(game,cart,trace,folder,frames,start,stop):\n    folder=Path(folder)\n    game,cart,trace=Path(game).resolve(),Path(cart).resolve(),Path(trace).resolve()\n    if not(game.is_file() and cart.is_file() and trace.is_file()):\n        raise FileNotFoundError('executable, cart ou trace nao encontrado')\n    if min(frames)<=start:raise ValueError('primeira captura precisa ocorrer depois do inicio do controle')\n    (folder/'assets').mkdir(parents=True,exist_ok=True)\n    shutil.copy2(cart,folder/'assets'/'cart-data.bin')\n    (folder/'input.txt').write_text(make_replay(trace,start,stop),encoding='utf-8')\n    cap=folder/'captures'\n    if cap.exists():shutil.rmtree(cap)\n    env=os.environ.copy()\n    for k in list(env):\n        if k.startswith('FORJA65_SPC_') or k in ('FORJA65_FRAME_HASHES','FORJA65_INPUT_RECORD'):\n            env.pop(k,None)\n    env.update(FORJA65_HEADLESS='1',FORJA65_UNCAPPED='1',FORJA65_CAPTURE_STOP='1',\n               FORJA65_HEADLESS_FRAMES=str(max(frames)),FORJA65_CAPTURE_FRAMES=','.join(map(str,frames)),\n               FORJA65_CAPTURE_DIR=str(cap.resolve()),FORJA65_INPUT_REPLAY=str((folder/'input.txt').resolve()))\n    with (folder/'run.log').open('w',encoding='utf-8') as log:\n        result=subprocess.run([str(game)],cwd=folder,env=env,stdout=log,stderr=subprocess.STDOUT)\n    if result.returncode: raise RuntimeError(f'runtime falhou: {result.returncode}')\n    qa=folder/'forja65-qa-status.txt'\n    if not qa.is_file() or 'runtime_started=PASS' not in qa.read_text():\n        raise RuntimeError('execucao nao confirmou inicializacao')\n    for f in frames:\n        if not (cap/f'frame-{f}'/'oam-sprites.txt').is_file():\n            raise RuntimeError(f'faltou OAM no frame {f}')\n\n\ndef main():\n    ap=argparse.ArgumentParser(description=__doc__)\n    ap.add_argument('--output',type=Path,required=True)\n    ap.add_argument('--game',type=Path)\n    ap.add_argument('--cart',type=Path)\n    ap.add_argument('--trace',type=Path)\n    ap.add_argument('--frames',default='1875,1900,1925')\n    ap.add_argument('--start',type=int,default=1835)\n    ap.add_argument('--stop',type=int,default=2380)\n    ap.add_argument('--old-tiles',default='2,3,11,5')\n    ap.add_argument('--new-tiles',default='2,13,5,4')\n    ap.add_argument('--board',default='88,32,170,200')\n    ap.add_argument('--report',type=Path)\n    a=ap.parse_args()\n    try:\n        frames=tuple(int(v) for v in a.frames.split(','))\n        tiles=tuple(int(v) for v in a.old_tiles.split(','))\n        new=tuple(int(v) for v in a.new_tiles.split(','))\n        board=tuple(int(v) for v in a.board.split(','))\n        if len(board)!=4 or len(tiles)!=4 or len(new)!=4 or len(set(tiles))!=4 or len(set(new))!=4:\n            raise ValueError('tiles/regiao invalidos')\n        if a.game:\n            if not(a.cart and a.trace):raise ValueError('--game requer --cart e --trace')\n            run(a.game,a.cart,a.trace,a.output,frames,a.start,a.stop)\n        r=validate(a.output,frames,tiles,new,board)\n        out=a.report or a.output/'resultado-travamento.json';out.parent.mkdir(parents=True,exist_ok=True)\n        out.write_text(json.dumps(r,indent=2)+'\\n',encoding='utf-8')\n        print('LOCK_HANDOFF_PASS',r['frames'],flush=True)\n        return 0\n    except (OSError,ValueError,RuntimeError) as exc:\n        print('LOCK_HANDOFF_FAIL',exc,file=sys.stderr)\n        return 2\n\nif __name__=='__main__':sys.exit(main())\n";
  const files={'src/pcm_audio_output.hpp':forja65PcmAudioHeader,'CMakeLists.txt':cmWithPpu,'BUILD-WINDOWS.cmd':buildCmd,'BUILD-QUALITY-WINDOWS.cmd':qualityCmd,'RUN-WINDOWS.cmd':runCmd,'RUN-HEADLESS.cmd':headlessCmd,'RUN-ORACLE.cmd':oracleCmd,'RUN-CAPTURE-SCENE.cmd':captureCmd,'RUN-CAPTURE-TIMELINE.cmd':captureTimelineCmd,'RUN-INPUT-RECORD.cmd':recordCmd,'RUN-INPUT-REPLAY.cmd':replayCmd,'RUN-NATIVE-AUDIT.cmd':nativeAuditCmd,'RUN-NATIVE-MIGRATION.cmd':migrationCmd,'RUN-NATIVE-CUTOVER.cmd':nativeCutoverCmd,'RUN-NATIVE-AUDIO.cmd':nativeAudioCmd,'RUN-ROM-CONVERGE.cmd':romConvergeCmd,'PACKAGE-NATIVE-WITHOUT-ROM.cmd':packageNativeCmd,'RUN-NATIVE-PORT.cmd':nativePortRunCmd,'RUN-ROM-PROFILE.cmd':romProfileCmd,'BUILD-NATIVE-ROM-PACK.cmd':romPackCmd,'RUN-ROM-NATIVE.cmd':romNativeCmd,'RUN-CAPTURE-SPC.cmd':captureSpcCmd,'docs/HOST-RUNTIME.txt':hostDoc,'docs/VIDEO.txt':"Forja65 REV198 - video do port (filtros e resolucao 4:3)\n\nTeclas na janela:\n  F7 / Shift+F7   proximo / anterior filtro\n  F8 / Shift+F8   proxima / anterior resolucao\n  F10             aspecto 4:3 (TV) -> 8:7 (pixel do SNES) -> 1:1 (pixel quadrado)\n  F11 ou Alt+Enter tela cheia (Esc sai)\n  F12             salva forja65-shot-NNN.bmp com o filtro aplicado\n\nFiltros: sharp (padrao, pixel nitido sem serrilhado de escala), nearest, bilinear, fxaa, scale2x, scale3x,\n  scale3x-fxaa, crt (linhas de varredura + mascara RGB), lcd (grade), cas (bilinear + nitidez AMD CAS).\nResolucoes: auto, 640x480, 800x600, 960x720, 1024x768, 1152x864, 1280x960, 1400x1050, 1440x1080, 1600x1200,\n  1920x1440, 2048x1536, 2880x2160 (todas 4:3). Qualquer LxA tambem vale: a imagem e encaixada sem esticar.\nNa tela cheia a imagem fica centralizada com bordas pretas; se a resolucao escolhida for maior que o monitor, e reduzida mantendo a proporcao.\n\nAs escolhas ficam em forja65-video.ini (criado na 1a execucao, pode editar). Variaveis de ambiente tem prioridade:\n  FORJA65_VIDEO_FILTER=fxaa  FORJA65_VIDEO_RESOLUTION=1440x1080  FORJA65_VIDEO_ASPECT=4:3  FORJA65_VIDEO_FULLSCREEN=1\n  FORJA65_VIDEO_CRT_MASK=70  FORJA65_VIDEO_SHARPEN=60  FORJA65_VIDEO_THREADS=n  FORJA65_VIDEO_FXAA_SCALE=1..4\n  FORJA65_VIDEO_LEGACY=1 volta a apresentacao antiga (escala inteira, sem filtros).\n\nO filtro roda so no host, sobre o quadro pronto do PPU: nao muda CPU, PPU, APU, replays nem hashes de quadro.\n",'docs/ORACLE-RUNTIME.txt':'Forja65 Oracle Runtime\n\n1. Execute BUILD-WINDOWS.cmd.\n2. Rode RUN-ORACLE.cmd.\n3. Se o runtime encontrar destino/estado/retorno ainda nao recompilado, ele grava forja65-oracle-hints.txt sem duplicatas.\n4. Na Forja65, use Importar Oracle/hints. A ROM e reanalisada automaticamente com o conhecimento acumulado.\n5. Gere novamente o port.\n\nPara JMP/JSR (abs,X), um alvo observado tambem pode revelar vizinhos plausiveis da mesma tabela ROM, reduzindo rodadas manuais.\n','docs/DETERMINISTIC-QA.txt':'Forja65 Deterministic QA\n\nRUN-INPUT-RECORD.cmd grava controles por frame. RUN-INPUT-REPLAY.cmd reproduz o mesmo trace. FORJA65_FRAME_HASHES=1 grava hashes de framebuffer/WRAM/PC por frame. Compare forja65-frame-hashes.txt entre builds para detectar regressao deterministica.\n','docs/NATIVE-DEPENDENCY-AUDIT.txt':nativeAuditDoc,'docs/NATIVE-HARDWARE-MIGRATION.txt':'Forja65 v0.3.29 - native hardware cutover\n\nPPU: FORJA65_PPU_MODE=state usa state-only + scanout C++; o relatorio agora separa ppu_native_* de ppu_fallback_* e PPU_NATIVE_ONLY so fica YES com fallback zero.\nDMA/HDMA: FORJA65_DMA_MODE=native mantem fast-path B-bus e mede bytes native/fallback.\nSPC700: captura + hook AOT continuam disponiveis.\nDSP: FORJA65_AUDIO_MODE=native avanca o mixer BRR/DSP C++ a 32 kHz pelo master clock, gera PCM e pode salvar forja65-native-audio.wav com FORJA65_AUDIO_DUMP=1.\nROM: RUN-ROM-CONVERGE.cmd faz profile -> pack -> teste native-only. PACKAGE-NATIVE-WITHOUT-ROM.cmd so cria native-release quando o teste passa e nao copia cart-data.bin.\n','docs/EQUIVALENCE-ORACLE.txt':'Equivalence harness (TEST ONLY)\n\nO game final nao contem interpretador. Gere tests/equivalence-cases.txt com resultados esperados obtidos da rotina 65C816 original em um oracle de teste separado. Cada linha aceita entry,a,x,y,s,d,db,pb,e,m,x8,c e expect_a/expect_x/expect_y/expect_s/expect_d/expect_db/expect_pb/expect_c. O CTest equivalence_vectors valida o C++ nativo contra esses vetores; sem vetores ele aparece como SKIP.\n','tests/runtime_smoke.cpp':runtimeSmoke,'tests/scene_capture_smoke.cpp':sceneCaptureSmoke,'tests/oracle_learning_smoke.cpp':oracleLearningSmoke,'tests/deterministic_input_smoke.cpp':deterministicInputSmoke,'tests/native_dependency_smoke.cpp':nativeDependencySmoke,'tests/native_migration_smoke.cpp':nativeMigrationSmoke,'tools/rom_pack_builder.cpp':romPackBuilder,'tests/equivalence_runner.cpp':equivalenceRunner,'tools/gameplay_transition_qa.py':gameplayQaScript,'tools/gameplay_controls_qa.py':gameplayControlsQaScript,'tools/gameplay_wall_qa.py':gameplayWallQaScript,'tools/gameplay_lock_qa.py':gameplayLockQaScript,'tests/equivalence-cases.txt':'# Vetores esperados do oracle 65C816 de teste. Ex.: entry=0x808000 a=0x1 expect_a=0x2\n','src/runtime.hpp':runtimeWithCheckpoint,'src/forja_checkpoint.hpp':forjaCheckpointHeader,'tools/near-crash-checkpoint.py':forjaCheckpointRunner,'docs/CHECKPOINTS.txt':forjaCheckpointDocs,'CHECKPOINT-CREATE-WINDOWS.cmd':forjaCheckpointCreate.replace(/\r?\n/g,'\r\n'),'CHECKPOINT-RESUME-WINDOWS.cmd':forjaCheckpointResume.replace(/\r?\n/g,'\r\n'),'src/generated.hpp':h,'src/dispatch.cpp':dispatchWithCheckpoint,'src/main.cpp':checkpointMainFinal,...unitFiles,'assets/cart-data.bin':rom.data,'analysis.json':analysis,'compatibility-report.txt':reportText(a),'README.txt':`Port C++ gerado pelo Forja65 ${VERSION} para ${a.title}.\n\nA v0.3.29 avanca o cutover nativo: PPU mede fallback real e pode provar PPU_NATIVE_ONLY; DSP/BRR roda em clock nativo de 32 kHz e gera PCM/WAV; ROM mostra cobertura do pack, ganha convergencia automatica e empacotamento sem cart-data.bin quando o teste native-only passa.\n\nA v0.3.28 iniciou a retirada real do hardware virtual: PPU state-only/native scanout, DMA/HDMA B-bus fast-path, captura+hook AOT de SPC700 e pack esparso de dados ROM.\n\nA v0.3.27 adiciona auditoria de dependencia nativa inspirada no SuperMarioWorldRecomp: contadores por frame de ROM/WRAM/PPU/APU/DMA/HDMA, primeiro PC que toca cada subsistema, relatorio final e RUN-NATIVE-AUDIT.cmd.\n\nA v0.3.26 adiciona QA deterministico e equivalencia: hints presos ao hash da ROM, replay/gravacao de controles por frame, hashes de framebuffer/WRAM, build strict/sanitizers, manifesto de integridade e harness de vetores ROM↔C++.\n\nA v0.3.25 adiciona Oracle runtime generico: fluxos, estados e retornos dinamicos desconhecidos viram hints unicos reaproveitaveis; JMP/JSR (abs,X) observados podem expandir automaticamente tabelas vizinhas. Use RUN-ORACLE.cmd e reimporte forja65-oracle-hints.txt na interface.\n\nA v0.3.23 mantem a fundacao de host do DKC3 Native PC: XInput + teclado, pacing por relogio em vez de Sleep(16), modo headless sem janela, CTest/runtime_smoke e scripts BUILD/RUN Windows. A camada 65C816 continua sendo recompilada pela Forja; estas mudancas melhoram o host PC e o diagnostico, sem misturar logica especifica do DKC3.\n\nA v0.3.23 tambem incorpora da arquitetura DKC3 v0.7.10 um pipeline generico de captura de cena PPU: VRAM/CGRAM/OAM, NPAL/NTIL/NMAP/NSCENE, camada de sprites OAM em NSPR, preview PPM, hash do framebuffer, hash da ROM e manifesto de integridade. Use RUN-CAPTURE-SCENE.cmd N para capturar um frame.\n\nA base v0.3.21 de Carry (C), runtime hints, STACK-RTL, shards estaveis, jump tables, interrupcoes, mirrors, SPC700 e dispatcher retomavel permanece ativa.\n\nFORJA65_HEADLESS=1 executa sem janela. FORJA65_HEADLESS_FRAMES limita frames em testes. FORJA65_UNCAPPED=1 remove o pacing de apresentacao. FORJA65_WATCHDOG_INSTRUCTIONS interrompe loops longos e grava forja65-crash-trace.txt.\n\nStatus atual: ${a.status}.\n`};
  files['RUN-WINDOWS-AUDIO.cmd']='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_AUDIO_GAIN=100\r\nset FORJA65_AUDIO_DUMP=0\r\nset FORJA65_HEADLESS=0\r\ncall RUN-WINDOWS.cmd\r\n';
  files['RUN-NATIVE-AUDIO.cmd']='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_AUDIO_MODE=native\r\nset FORJA65_AUDIO_DUMP=1\r\nset FORJA65_HEADLESS=1\r\nset FORJA65_HEADLESS_FRAMES=%~1\r\nif "%FORJA65_HEADLESS_FRAMES%"=="" set FORJA65_HEADLESS_FRAMES=2200\r\ncall RUN-WINDOWS.cmd\r\necho Audio WAV e diagnostico na pasta onde game.exe foi executado.\r\npause\r\n';
  for(const profile of ['reference','legacy']){
    const name='RUN-WINDOWS-SPC-'+profile.toUpperCase()+'.cmd';
    files[name]='@echo off\r\nsetlocal\r\ncd /d "%~dp0"\r\nset FORJA65_SPC_PROFILE='+profile+'\r\ncall RUN-WINDOWS-AUDIO.cmd\r\n';
  }
  files['BUILD-WINDOWS.cmd']=files['BUILD-WINDOWS.cmd'].replace('copy /Y RUN-WINDOWS.cmd bin\\RUN-WINDOWS.cmd >nul\r\n',
    'copy /Y RUN-WINDOWS.cmd bin\\RUN-WINDOWS.cmd >nul\r\ncopy /Y RUN-WINDOWS-AUDIO.cmd bin\\RUN-WINDOWS-AUDIO.cmd >nul\r\ncopy /Y RUN-WINDOWS-SPC-REFERENCE.cmd bin\\RUN-WINDOWS-SPC-REFERENCE.cmd >nul\r\ncopy /Y RUN-WINDOWS-SPC-LEGACY.cmd bin\\RUN-WINDOWS-SPC-LEGACY.cmd >nul\r\n');
  files['RUN-WINDOWS-AUDIO-INTERLEAVED.cmd']='@echo off\r\nsetlocal\r\nset FORJA65_APU_DSP_INTERLEAVE=1\r\ncall "%~dp0RUN-WINDOWS-AUDIO.cmd"\r\n';
  files['BUILD-WINDOWS.cmd']=files['BUILD-WINDOWS.cmd'].replace('copy /Y RUN-WINDOWS-AUDIO.cmd bin\\RUN-WINDOWS-AUDIO.cmd >nul\r\n','copy /Y RUN-WINDOWS-AUDIO.cmd bin\\RUN-WINDOWS-AUDIO.cmd >nul\r\ncopy /Y RUN-WINDOWS-AUDIO-INTERLEAVED.cmd bin\\RUN-WINDOWS-AUDIO-INTERLEAVED.cmd >nul\r\n');
  files['RUN-WINDOWS-AUDIO-48KHZ.cmd']='@echo off\r\nsetlocal\r\nset FORJA65_AUDIO_DEVICE_RATE=48000\r\ncall "%~dp0RUN-WINDOWS-AUDIO.cmd"\r\n';
  files['BUILD-WINDOWS.cmd']=files['BUILD-WINDOWS.cmd'].replace('copy /Y RUN-WINDOWS-AUDIO-INTERLEAVED.cmd bin\\RUN-WINDOWS-AUDIO-INTERLEAVED.cmd >nul\r\n','copy /Y RUN-WINDOWS-AUDIO-INTERLEAVED.cmd bin\\RUN-WINDOWS-AUDIO-INTERLEAVED.cmd >nul\r\ncopy /Y RUN-WINDOWS-AUDIO-48KHZ.cmd bin\\RUN-WINDOWS-AUDIO-48KHZ.cmd >nul\r\n');
  files['RUN-WINDOWS-AUDIO-LEGACY-CLOCK.cmd']='@echo off\r\nsetlocal\r\nset FORJA65_DSP_CLOCK=legacy\r\ncall "%~dp0RUN-WINDOWS-AUDIO.cmd"\r\n';
  files['docs/PCM-DSP-v0435.txt']='DSP v0.4.35: S-DSP FIR com buffer de 15 bits, 8 taps na ordem correta, overflow assinado 16-bit e saturacao final; noise clock segue contador ADSR e volumes DSP usam divisor 128. Para desativar isoladamente use FORJA65_DSP_ECHO_FIR=legacy, FORJA65_DSP_NOISE_CLOCK=legacy ou FORJA65_DSP_VOLUMES=legacy. Echo RAM writes continuam opt-in: FORJA65_ECHO_RAM_WRITES=1 (pode tocar memoria SPC). WinMM 32000 Hz por padrao, 48000 Hz opcional com RUN-WINDOWS-AUDIO-48KHZ.cmd (interpolacao linear 3:2). O WAV continua PCM 32000 Hz. Nenhuma alegacao de emulacao bit-exact.\n';
  files['docs/AUDIO-REALTIME-CROSSFEED.txt']='Audio PCM v0.4.23 cruzado do Tetris: saída WinMM/32kHz/stereo no Windows. RUN-WINDOWS-AUDIO.cmd inicia janela com som; RUN-NATIVE-AUDIO.cmd gera WAV headless (2200 frames). FORJA65_AUDIO_GAIN=0..400, FORJA65_AUDIO_DUMP=1, FORJA65_AUDIO_MODE=native. PCM no Windows: FORJA65_AUDIO_SYNC=1 (padrao, espera quando fila cheia) e FORJA65_AUDIO_DRAIN=1 (padrao, preserva cauda na saida); use 0 para desativar. Medicoes: pcm_buffer_wait_ms, pcm_drain_wait_ms, frames_dropped. Consulte forja65-audio-report.txt. Emulacao DSP experimental; audio nao comprova exatidao SNES.\n';
