  // Generic regressions belong to every generated ROM project.
  files['tests/return_stack_guard_v0393.cpp']="#include \"runtime.hpp\"\n#include <cassert>\n#include <iostream>\nint main(){SnesRuntime h;CpuState c;c.enforceEmulation();\n c.push16Value(h,0x8122);h.pushNativeReturn(0x8123,false,c);\n assert(h.nativeReturnMatches(0x8123,false,c));\n // A PEA-style trampoline uses a different physical stack slot even if its\n // destination coincides with the outer JSR's continuation.\n c.push16Value(h,0x8122);\n assert(!h.nativeReturnMatches(0x8123,false,c));\n auto before=h.nativeReturns.size();h.retireRedirectedNativeReturn(c,false);\n assert(h.nativeReturns.size()==before);c.pop16Value(h);\n assert(h.nativeReturnMatches(0x8123,false,c));\n // Authorized redirect at the real call frame removes its bookkeeping.\n h.retireRedirectedNativeReturn(c,false);c.pop16Value(h);\n assert(h.nativeReturns.empty()&&c.s==0x1ff);\n // Nested calls, repeating destinations: retire exactly the active slot.\n c.e=false;c.s=0x1234;c.push16Value(h,0x9000);h.pushNativeReturn(0x9001,false,c);\n c.push16Value(h,0x9000);h.pushNativeReturn(0x9001,false,c);\n h.retireRedirectedNativeReturn(c,false);c.pop16Value(h);\n assert(h.nativeReturns.size()==1&&h.nativeReturnMatches(0x9001,false,c));\n h.retireRedirectedNativeReturn(c,false);c.pop16Value(h);\n assert(h.nativeReturns.empty()&&c.s==0x1234);\n // No numeric ordering assumption: native stack can wrap through zero.\n c.s=1;c.push16Value(h,0x7777);assert(c.s==0xffff);h.pushNativeReturn(0x7778,false,c);\n h.retireRedirectedNativeReturn(c,false);c.pop16Value(h);assert(c.s==1&&h.nativeReturns.empty());\n std::cout<<\"stack-position guard PASS PEA/nested/wrap\\n\";\n}\n";
  files['tests/hardware_color_hdma_v0392.cpp']="#include \"runtime.hpp\"\n#include <cassert>\n#include <iostream>\nint main(int argc,char**argv){\n if(argc>1&&std::string(argv[1])==\"blend\"){\n  for(int a=0;a<32;a++)for(int b=0;b<32;b++)for(bool sub:{false,true})for(bool half:{false,true}){\n   int expected=sub?std::max(0,a-b):a+b;if(half)expected>>=1;expected=std::min(31,expected);\n   auto packed=[](int x){return std::uint16_t(x|(x<<5)|(x<<10));};\n   if(PpuState::blend15(packed(a),packed(b),sub,half)!=packed(expected)){std::cerr<<\"blend mismatch a=\"<<a<<\" b=\"<<b<<\" half=\"<<half<<\" subtract=\"<<sub<<\"\\n\";return 1;}\n  }std::cout<<\"blend: PASS 4096 vectors\\n\";return 0;\n }\n if(argc>1&&std::string(argv[1])==\"windows\"){\n  PpuState p;p.brightness=15;p.cgram[0]=20;p.fixedR=8;p.cgadsub=0x60;p.cgwsel=0x30;\n  // Math disabled by color window: preserve main, including the half flag.\n  assert(p.finalMain15(0,0)==20);\n  p.cgwsel=2; // Empty subscreen uses COLDATA, with halve suppressed.\n  assert(p.finalMain15(0,0)==28);\n  p.cgwsel=0xc0; // Clip main to black: halve must be suppressed.\n  assert(p.finalMain15(0,0)==8);\n  std::cout<<\"color window/subscreen backdrop: PASS\\n\";return 0;\n }\n // Direct HDMA crosses $7E:FFFF inside the two-byte pattern; next byte\n // must come from $7E:0000, never $7F:0000.\n for(bool native:{false,true})for(bool indirect:{false,true}){\n  SnesRuntime h;h.headless=true;h.nativeDmaEnabled=native;h.ppu.forceBlank=true;h.beginFrame();h.currentScanline=225;h.currentMasterCycle=100;\n  auto&d=h.dma[0];d.dmap=1|(indirect?0x40:0);d.bbad=0x26;d.a1b=0x7e;d.a2a=0xffff;d.dasb=0x7e;d.das=0xffff;h.ram[0xffff]=12;h.ram[0]=34;h.ram[0x10000]=56;\n  h.hdmaActive=1;d.ntrl=2;h.hdmaLines[0]=2;h.hdmaTransfer[0]=true;h.executeHdmaLine();\n  if(h.ppu.wh[0]!=12||h.ppu.wh[1]!=34){std::cerr<<\"HDMA payload escaped bank native=\"<<native<<\" indirect=\"<<indirect<<\" value=\"<<unsigned(h.ppu.wh[1])<<\"\\n\";return 1;}\n  assert((indirect?d.das:d.a2a)==1);\n  // The two-byte indirect pointer itself also wraps inside A1B.\n  if(indirect){h.hdmaActive=1;h.hdmaLines[0]=0;d.a2a=0xfffe;h.ram[0xfffe]=2;h.ram[0xffff]=0x00;h.ram[0]=0x80;h.ram[0x10000]=0x90;h.ram[0x8000]=7;h.ram[0x8001]=9;h.reloadHdmaChannel(0);h.executeHdmaLine();assert(h.ppu.wh[0]==7&&h.ppu.wh[1]==9);assert(d.das==0x8002);}\n }std::cout<<\"HDMA bank-wrap: PASS direct/indirect native/fallback\\n\";\n}\n";
  files['tests/sprite_planes_v0392.cpp']="#include \"runtime.hpp\"\n#include <iostream>\n#include <cassert>\nint main(){PpuState p;for(unsigned i=0;i<128;i++)p.oam[i*4+1]=100;p.oam[0]=0;p.oam[1]=0;p.vram[0]=255;p.cgram[258]=31;auto row=p.buildSpriteRow(0);assert(row[0].valid);\n#ifdef FORJA65_TEST_VRAM_COUNT\nstd::cout<<\"OBJ row VRAM reads=\"<<p.testReads<<\"\\n\";if(p.testReads>4){std::cerr<<\"OBJ row repeatedly fetches the same 4 plane bytes\\n\";return 1;}\n#endif\n\n unsigned seed=123;auto rnd=[&](){seed=seed*1664525u+1013904223u;return seed>>24;};\n for(unsigned n=0;n<64;n++){for(auto&v:p.vram)v=rnd();for(auto&v:p.oam)v=rnd();for(auto&v:p.cgram)v=rnd();p.obsel=rnd();p.regs[3]=rnd();p.oamAddr=rnd();for(int y:{0,7,111,223,255}){auto r=p.buildSpriteRow(y);for(int x=0;x<256;x++){auto a=r[x],b=p.sampleSprites(x,y);assert(a.valid==b.valid);if(a.valid)assert(a.c15==b.c15&&a.objPal==b.objPal&&a.priority==b.priority&&a.oamIndex==b.oamIndex);}}}\n std::cout<<\"OBJ cached/scalar equivalence PASS\\n\";\n}\n";
