function spcDecodeOne(cap,pc){pc&=0xFFFF;const op=cap.data[pc],m=SPC_META[op]||['OP_'+hex(op,2),'imp',1,'unsupported'],len=m[2];let operand=0,raw=[op];for(let i=1;i<len;i++){const b=cap.data[(pc+i)&0xFFFF];raw.push(b);operand|=b<<(8*(i-1));}let target=null;if(m[1]==='rel'){const r=operand&255,sv=(r&0x80)?r-256:r;target=(pc+len+sv)&0xFFFF;}else if(['CALL','JMP'].includes(m[0]))target=operand&0xFFFF;return {pc,opcode:op,mnemonic:m[0],mode:m[1],size:len,operand,raw,status:m[3],target};}
