        const cmp=prior(6),branch=prior(4);
        const inside=t=>{const d=(pc-t)&65535;return d<=4||t===pc;};
        if(cmp?.opcode===0x68&&cmp.operand>0&&cmp.operand<=128&&branch?.opcode===0xb0&&!inside(branch.target&65535)){
          const out=[];for(let x=0;x<cmp.operand;x++)out.push(x*2);return {indices:out,proof:branch.target===((pc+3)&65535)?'cmp-bcs-asl-movx':'cmp-bcs-any-asl-movx'};
        }
        const and=prior(4);
