  const body=a.instructions.map(i=>`S_${hex(i.pc,4)}:\n  if(forja65SpcPeek(apu,apu.spc.pc)!=0x${hex(i.opcode,2)}u)return 0;\n  return forja65SpcExecute<0x${hex(i.opcode,2)}u>(apu);`).join('\n');
