function generateSpcProject(cap,a){const src=spcCpp(cap,a);return {'pcm_audio_output.hpp':forja65PcmAudioHeader,'CMakeLists.txt':'cmake_minimum_required(VERSION 3.20)\nproject(Forja65SpcNative LANGUAGES CXX)\nset(CMAKE_CXX_STANDARD 20)\nadd_executable(spc_test main.cpp spc700_native.cpp)\n','runtime.hpp':runtimeHpp().replace('(controlMode?0u:2u)','2u'),'spc700_native.cpp':src,'spc700-report.txt':spcReportText(a),'spc700-disasm.txt':a.instructions.map(spcFormat).join('\n'),'capture.bin':cap.data,'capture.txt':Object.entries(cap.manifest).map(([k,v])=>k+'='+v).join('\n'),'main.cpp':'#include "runtime.hpp"\n#include <iostream>\nstruct SpcCpuState; void forja65_spc_run_slice(SpcCpuState&,ApuBridge&,unsigned); void forja65_native_spc_tick(ApuBridge&,unsigned); int main(){std::cout<<"Forja65 SPC700 native module gerado\\n";return 0;}\n'};}

