// ---------------- REV205: medicao de desempenho do port (FORJA65_PERF) ----------------
// Mede, sem mudar a emulacao, o tempo de cada quadro (sem o tempo da janela/espera), o tempo do PPU e o
// ritmo de instrucoes. Liga com FORJA65_PERF=1 (ou FORJA65_PERF_OUT=arquivo.json); desligado custa um teste
// de bool por segmento de linha. O relatorio fica em forja65-perf.json.
const FORJA65_REV205_PERF_PRELUDE=`// Forja65 REV205: medicao de desempenho (FORJA65_PERF=1 / FORJA65_PERF_OUT=arquivo.json)
struct ForjaPerfScope{std::uint64_t*acc;std::chrono::steady_clock::time_point t0{};explicit ForjaPerfScope(std::uint64_t*a):acc(a){if(acc)t0=std::chrono::steady_clock::now();}
  ~ForjaPerfScope(){if(acc)*acc+=(std::uint64_t)std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-t0).count();}};
struct ForjaPerfState{bool on{};std::uint64_t ppuNs{},hostNs{},ppuAtLast{},hostAtLast{},instrAtStart{};std::chrono::steady_clock::time_point start{},last{};
  std::vector<std::uint32_t> frameUs,ppuUs;std::vector<std::uint64_t> instr;
  static ForjaPerfState fromEnv(){ForjaPerfState p;const char*a=std::getenv("FORJA65_PERF");const char*b=std::getenv("FORJA65_PERF_OUT");
    p.on=(a&&*a&&*a!='0')||(b&&*b);p.start=p.last=std::chrono::steady_clock::now();if(p.on){p.frameUs.reserve(1u<<16);p.ppuUs.reserve(1u<<16);p.instr.reserve(1u<<16);}return p;}};
`;
const FORJA65_REV205_PERF_MEMBERS=`  // REV205: desempenho por quadro (ver ForjaPerfState)
  ForjaPerfState perf=ForjaPerfState::fromEnv();
  void perfFrame(){
    if(!perf.on){return;}const auto now=std::chrono::steady_clock::now();
    std::uint64_t ns=(std::uint64_t)std::chrono::duration_cast<std::chrono::nanoseconds>(now-perf.last).count();
    const std::uint64_t host=perf.hostNs-perf.hostAtLast;ns=ns>host?ns-host:0u;
    perf.frameUs.push_back((std::uint32_t)std::min<std::uint64_t>(ns/1000u,0xFFFFFFFFu));
    perf.ppuUs.push_back((std::uint32_t)std::min<std::uint64_t>((perf.ppuNs-perf.ppuAtLast)/1000u,0xFFFFFFFFu));
    perf.instr.push_back(cpuInstructionCount);
    perf.last=now;perf.hostAtLast=perf.hostNs;perf.ppuAtLast=perf.ppuNs;
  }
  void writePerfReport(){
    if(!perf.on){return;}const char*o=std::getenv("FORJA65_PERF_OUT");const std::string path=o&&*o?o:"forja65-perf.json";
    std::vector<std::uint32_t> f=perf.frameUs;
    // o 1o quadro inclui a carga do port e o boot do host: fica fora das estatisticas
    if(!f.empty())f.erase(f.begin());
    std::uint64_t sum=0;for(auto v:f)sum+=v;std::uint64_t ppu=0;for(std::size_t i=1;i<perf.ppuUs.size();++i)ppu+=perf.ppuUs[i];
    std::vector<std::uint32_t> s=f;std::sort(s.begin(),s.end());
    auto pct=[&](double q)->double{if(s.empty())return 0.0;std::size_t i=(std::size_t)std::min<double>((double)s.size()-1.0,q*(double)(s.size()-1));return s[i]/1000.0;};
    const double secs=sum/1e6,fps=secs>0?f.size()/secs:0.0;const double ntsc=21477272.7/(1364.0*262.0-2.0);
    std::size_t over=0;for(auto v:f)if(v>16639u)over++;
    const std::uint64_t instr=perf.instr.size()>1?perf.instr.back()-perf.instr.front():0u;
    std::ofstream out(path,std::ios::trunc);if(!out)return;
    out<<std::fixed<<std::setprecision(3)
       <<"{\\n \\"formato\\": \\"forja65-rev205-perf-1\\",\\n \\"quadros_medidos\\": "<<f.size()
       <<",\\n \\"emulacao_s\\": "<<secs<<",\\n \\"quadros_por_segundo\\": "<<fps<<",\\n \\"vezes_tempo_real_ntsc\\": "<<(fps/ntsc)
       <<",\\n \\"quadro_ms\\": {\\"media\\": "<<(f.empty()?0.0:sum/1000.0/f.size())<<", \\"p50\\": "<<pct(0.50)<<", \\"p95\\": "<<pct(0.95)<<", \\"p99\\": "<<pct(0.99)<<", \\"max\\": "<<pct(1.0)<<"}"
       <<",\\n \\"quadros_acima_de_16_64ms\\": "<<over
       <<",\\n \\"ppu_pct\\": "<<(sum?100.0*(double)ppu/(double)sum:0.0)
       <<",\\n \\"cpu_instrucoes\\": "<<instr<<",\\n \\"cpu_instrucoes_por_s\\": "<<(secs>0?instr/secs:0.0)
       <<",\\n \\"janela_e_espera_s\\": "<<(perf.hostNs/1e9)<<",\\n \\"apu_aot_instrucoes\\": "<<apu.spcAotInstructions<<",\\n \\"apu_aot_misses\\": "<<apu.spcAotMisses
       <<",\\n \\"quadro_ms_serie_a_cada_60\\": [";
    for(std::size_t i=0;i<f.size();i+=60){if(i)out<<", ";out<<(f[i]/1000.0);}
    out<<"]\\n}\\n";
    std::printf("FORJA65_PERF quadros=%zu fps=%.1f tempo_real=%.2fx p99=%.2fms ppu=%.1f%%\\n",f.size(),fps,fps/ntsc,pct(0.99),sum?100.0*(double)ppu/(double)sum:0.0);
  }
`;
function attachRev205Perf(files){
  let t=files['src/runtime.hpp'];
  if(!t||t.includes('struct ForjaPerfScope'))return files;
  const rep=(from,to,label)=>{if(!t.includes(from))throw new Error('REV205 perf anchor absent: '+label);t=t.replace(from,()=>to);};
  rep('struct SnesRuntime;\nstruct CpuState {',FORJA65_REV205_PERF_PRELUDE+'struct SnesRuntime;\nstruct CpuState {','prelude');
  rep('  void renderRuntimeSegment(unsigned line,unsigned x0,unsigned x1){\n',
      '  void renderRuntimeSegment(unsigned line,unsigned x0,unsigned x1){\n    ForjaPerfScope perfScope(perf.on?&perf.ppuNs:nullptr);\n','ppu scope');
  rep('if(hostFrameReady){hostFrameReady=false;present();',
      'if(hostFrameReady){hostFrameReady=false;{ForjaPerfScope hostScope(perf.on?&perf.hostNs:nullptr);present();}','host scope');
  rep('  void endVblank(){finishAutoJoyRead(true);','  void endVblank(){perfFrame();finishAutoJoyRead(true);','frame mark');
  rep('  // REV134: controle remoto quadro a quadro com savestates por fork (FORJA65_CONTROL=1).\n',
      FORJA65_REV205_PERF_MEMBERS+'  // REV134: controle remoto quadro a quadro com savestates por fork (FORJA65_CONTROL=1).\n','members');
  files['src/runtime.hpp']=t;
  let m=files['src/main.cpp'];
  if(typeof m==='string'){
    const a='hw.writePpuRegisterProfile();hw.writeBootProbe();';
    if(!m.includes(a))throw new Error('REV205 perf anchor absent: main report');
    files['src/main.cpp']=m.replace(a,()=>a+'hw.writePerfReport();');
  }
  return files;
}

// ---------------- REV205: caminho rapido do compositor do PPU ----------------
// Modos 0, 1 e 3 sem mosaico e sem (pseudo-)hires: cada camada do segmento e decodificada uma vez por linha
// de tile (mesma decodificacao do cache de sampleBg) e a composicao segue as regras de compose()/finalMain15().
// FORJA65_PPU_FAST=0 volta ao caminho antigo; FORJA65_PPU_VERIFY=1 calcula os dois e registra divergencias
// em forja65-ppu-verify.txt (usa sempre o pixel do caminho antigo nesse modo).
const FORJA65_REV205_PPU_FAST=`  // REV205: caminho rapido do compositor (ver FORJA65_PPU_FAST / FORJA65_PPU_VERIFY)
  static int ppuFastMode(){static const int m=[](){const char*e=std::getenv("FORJA65_PPU_FAST");if(e&&*e=='0')return 0;
    const char*v=std::getenv("FORJA65_PPU_VERIFY");return(v&&*v&&*v!='0')?2:1;}();return m;}
  bool fastSegmentEligible()const{const unsigned m=bgmode&7u;if(m!=0u&&m!=1u&&m!=3u)return false;if(pseudoHires())return false;if(mosaic&0x0Fu)return false;return true;}
  void fastLayerRow(unsigned bg,int y,unsigned x0,unsigned x1,unsigned bpp,unsigned paletteBase,bool allowDirect,LayerPixel*out)const{
    const std::uint32_t mapBase=((std::uint32_t)(bgsc[bg]&0xFCu)<<9)&0xFFFFu,charBase=((std::uint32_t)(bgnba[bg]&7u)*0x2000u)&0xFFFFu;
    const unsigned sc=bgsc[bg]&3u,mapWTiles=(sc&1u)?64u:32u,mapHTiles=(sc&2u)?64u:32u;const bool big=((bgmode>>(4u+bg))&1u)!=0;
    const unsigned tileW=big?16u:8u,tileH=big?16u:8u,mapW=mapWTiles*tileW,mapH=mapHTiles*tileH;
    const int worldY=y+bgLineOffset(false)+(int)scrollY[bg];const unsigned wy=(unsigned)worldY&(mapH-1u),ty=wy/tileH;
    const auto depth=bgDepth(bg);const bool direct=bpp==8u&&allowDirect&&(cgwsel&1u);
    LayerPixel px8[8];unsigned cur=~0u;
    for(unsigned x=x0;x<x1;x++){
      const unsigned wx=(unsigned)((int)x+(int)scrollX[bg])&(mapW-1u);
      if((wx>>3)!=cur){
        cur=wx>>3;const unsigned tx=wx/tileW;
        const unsigned screenX=tx>>5,screenY=ty>>5,screen=screenX+screenY*((mapWTiles+31u)>>5),localX=tx&31u,localY=ty&31u;
        const std::uint32_t ep=(mapBase+screen*0x800u+((localY*32u+localX)*2u))&0xFFFFu;
        const std::uint16_t e=(std::uint16_t)(vram[ep]|(vram[(ep+1)&0xFFFFu]<<8));unsigned tile=e&0x3FFu;const unsigned pal=(e>>10)&7u;const bool pri=(e&0x2000u)!=0,hf=(e&0x4000u)!=0,vf=(e&0x8000u)!=0;
        unsigned px=wx&(tileW-1u),py=wy&(tileH-1u);if(hf)px=tileW-1u-px;if(vf)py=tileH-1u-py;
        if(tileW>8u){tile=(tile+(px>>3))&0x3FFu;}if(tileH>8u){tile=(tile+((py>>3)<<4))&0x3FFu;}py&=7u;
        unsigned planes[8]{};const std::uint32_t base=(charBase+tile*(bpp*8u)+py*2u)&0xFFFFu;
        for(unsigned plane=0;plane<bpp;plane++)planes[plane]=vram[(base+(plane>>1)*16u+(plane&1u))&0xFFFFu];
        for(unsigned k=0;k<8;k++){
          LayerPixel q{};q.valid=false;q.source=(std::uint8_t)bg;const unsigned bit=hf?k:7u-k;unsigned ci=0;
          for(unsigned plane=0;plane<bpp;plane++)ci|=((planes[plane]>>bit)&1u)<<plane;
          if(ci){if(direct)q.c15=directColor15(pal,ci);else if(bpp==8u)q.c15=palette15(ci);else q.c15=palette15(paletteBase+pal*(bpp==4u?16u:4u)+ci);
            q.priority=(std::uint8_t)(pri?depth.second:depth.first);q.valid=true;}
          px8[k]=q;
        }
      }
      out[x]=px8[wx&7u];
    }
  }
  bool renderFastSegment(std::vector<std::uint32_t>&fb,int y,unsigned x0,unsigned x1,std::size_t rowBase,const SpriteRow*sprites,BgTileRows*bgTiles)const{
    if(x1>256u)return false;
    const unsigned mode=bgmode&7u;struct Lay{unsigned n,bpp,pal;bool dc;};Lay ls[4];unsigned nl=0;
    if(mode==0u){ls[nl++]={3,2,96,false};ls[nl++]={2,2,64,false};ls[nl++]={1,2,32,false};ls[nl++]={0,2,0,false};}
    else if(mode==1u){ls[nl++]={2,2,0,false};ls[nl++]={1,4,0,false};ls[nl++]={0,4,0,false};}
    else{ls[nl++]={1,4,0,false};ls[nl++]={0,8,0,true};}
    const std::uint8_t used=(std::uint8_t)(tm|ts);if((used&0x10u)&&!sprites)return false;
    static thread_local std::array<std::array<LayerPixel,256>,4> buf;static thread_local std::array<std::uint8_t,256> win;
    for(unsigned i=0;i<nl;i++)if(used&(1u<<ls[i].n))fastLayerRow(ls[i].n,y,x0,x1,ls[i].bpp,ls[i].pal,ls[i].dc,buf[ls[i].n].data());
    // janelas: bit n = layerWindow(n,x) para as camadas 0..5, calculado so quando alguma janela esta ligada
    const bool anyWin=(w12sel|w34sel|wobjsel)!=0;
    if(anyWin)for(unsigned x=x0;x<x1;x++){std::uint8_t b=0;for(unsigned n=0;n<6;n++)if(layerWindow(n,(int)x))b|=(std::uint8_t)(1u<<n);win[x]=b;}
    const std::uint16_t back=palette15(0),fix=fixed15();const int verify=ppuFastMode()==2;
    auto comp=[&](unsigned x,bool sub)->LayerPixel{
      LayerPixel out{back,5,0,1,255,true};const std::uint8_t en=sub?ts:tm,wm=sub?tsw:tmw;
      for(unsigned i=0;i<nl;i++){const unsigned n=ls[i].n;if(!(en&(1u<<n)))continue;if((wm&(1u<<n))&&anyWin&&(win[x]&(1u<<n)))continue;
        const LayerPixel&q=buf[n][x];if(q.valid&&q.priority>out.priority)out=q;}
      if((en&0x10u)&&!((wm&0x10u)&&anyWin&&(win[x]&0x10u))){const LayerPixel&q=(*sprites)[x];if(q.valid&&q.priority>out.priority)out=q;}
      return out;};
    for(unsigned x=x0;x<x1;x++){
      const bool cw=anyWin&&(win[x]&0x20u);LayerPixel mainPx=comp(x,false);const bool clipped=regionMatch((cgwsel>>6)&3u,cw);if(clipped)mainPx.c15=0;
      bool math=false;if(mainPx.source<=3)math=(cgadsub&(1u<<mainPx.source))!=0;else if(mainPx.source==4)math=(cgadsub&0x10u)&&mainPx.objPal>=4;else math=(cgadsub&0x20u)!=0;
      std::uint16_t result=mainPx.c15;
      if(math&&!regionMatch((cgwsel>>4)&3u,cw)){LayerPixel subPx{};if(cgwsel&0x02u)subPx=comp(x,true);
        const std::uint16_t add=((cgwsel&0x02u)&&subPx.source!=5)?subPx.c15:fix;bool half=(cgadsub&0x40u)!=0&&!clipped;if((cgwsel&0x02u)&&subPx.source==5)half=false;
        result=blend15(result,add,(cgadsub&0x80u)!=0,half);}
      if(verify){const std::uint16_t ref=finalMain15((int)x,y,false,sprites,bgTiles);
        if(ref!=result){static unsigned logged=0;static std::uint64_t total=0;++total;if(logged<200){++logged;std::ofstream v("forja65-ppu-verify.txt",std::ios::app);
          if(v)v<<"y="<<y<<" x="<<x<<" mode="<<mode<<" ref="<<std::hex<<ref<<" fast="<<result<<" tm="<<unsigned(tm)<<" ts="<<unsigned(ts)<<" cgwsel="<<unsigned(cgwsel)<<" cgadsub="<<unsigned(cgadsub)<<std::dec<<" total="<<total<<"\\n";}}
        result=ref;}
      fb[rowBase+x]=rgba15(result);
    }
    return true;
  }
`;
function attachRev205PpuFast(files){
  let t=files['src/runtime.hpp'];
  if(!t||t.includes('bool renderFastSegment('))return files;
  const rep=(from,to,label)=>{if(t.split(from).length!==2)throw new Error('REV205 PPU anchor absent/duplicated: '+label);t=t.replace(from,()=>to);};
  rep('  void renderOutputSegment(std::vector<std::uint32_t>&fb,int y,unsigned x0,unsigned x1,',
      FORJA65_REV205_PPU_FAST+'  void renderOutputSegment(std::vector<std::uint32_t>&fb,int y,unsigned x0,unsigned x1,','methods');
  if(t.includes('unsigned logicalX=(ow==512u&&nativeWidth==256u)?x/2u:x;')){
    // base REV208: a tela pode ter canvas mais largo que a largura nativa; o caminho rapido so vale quando sao iguais
    rep('    for(unsigned x=x0;x<x1;x++){unsigned logicalX=(ow==512u&&nativeWidth==256u)?x/2u:x;',
        '    if(ow==nativeWidth&&ppuFastMode()&&fastSegmentEligible()&&renderFastSegment(fb,y,x0,x1,(std::size_t)row*ow,sprites,&bgTiles))return;\n'+
        '    for(unsigned x=x0;x<x1;x++){unsigned logicalX=(ow==512u&&nativeWidth==256u)?x/2u:x;','hook');
  }else{
  rep('    for(unsigned x=x0;x<x1;x++)fb[(std::size_t)row*ow+x]=rgba15(finalMain15((int)x,y,false,sprites,&bgTiles));\n',
      '    if(ppuFastMode()&&fastSegmentEligible()&&renderFastSegment(fb,y,x0,x1,(std::size_t)row*ow,sprites,&bgTiles))return;\n'+
      '    for(unsigned x=x0;x<x1;x++)fb[(std::size_t)row*ow+x]=rgba15(finalMain15((int)x,y,false,sprites,&bgTiles));\n','hook');
  }
  files['src/runtime.hpp']=t;
  return files;
}

// ---------------- REV205: color math em hires/pseudo-hires como no ares/bsnes ----------------
// Em hires (modo 5/6 e pseudo-hires) cada ponto sai como [pixel da sub-tela, pixel da tela principal]. O pixel da
// sub-tela passa pela mesma color math, mas com o estado (habilitacoes, modo e cor) do ponto ANTERIOR da tela
// principal; o primeiro pixel da linha sai transparente (preto). Fonte: ares sfc/ppu/dac.cpp (ISC) e
// bsnes sfc/ppu/screen.cpp. FORJA65_HIRES_MATH=legacy volta ao comportamento anterior (sub-tela sem math).
const FORJA65_REV205_HIRES=`  // REV205: estado da color math entre pontos em hires (ares dac.cpp: math.above/below, blendMode, colorHalve)
  struct HiresMath{std::uint16_t aboveColor{},belowColor{};bool aboveEn{},belowEn{},blendMode{},colorHalve{},transparent{true};};
  mutable HiresMath hiresMath{};
  static bool hiresMathLegacy(){static const bool v=[](){const char*e=std::getenv("FORJA65_HIRES_MATH");return e&&std::string(e)=="legacy";}();return v;}
  void renderHiresMathSegment(std::vector<std::uint32_t>&fb,int sy,unsigned x0,unsigned x1,std::size_t rowBase,bool trueHires,const SpriteRow*sprites,BgTileRows*bgTiles)const{
    auto&st=hiresMath;const bool colorSub=(cgadsub&0x80u)!=0;const std::uint16_t fix=fixed15();
    for(unsigned ox=x0;ox<x1;ox++){
      const unsigned lx=ox>>1;
      if(ox==0u){st=HiresMath{};st.aboveColor=palette15(0);}
      std::uint16_t out;
      if((ox&1u)==0u){
        // below(): cor da sub-tela deste ponto; math com o estado do ponto anterior
        const LayerPixel sub=compose(trueHires?(int)ox:(int)lx,sy,true,trueHires,sprites,bgTiles);
        st.transparent=sub.source==5;st.belowColor=sub.c15;
        if(!st.belowEn)out=st.aboveEn?st.belowColor:0;
        else out=blend15(st.aboveEn?st.belowColor:0,st.blendMode?st.aboveColor:fix,colorSub,st.colorHalve);
      }else{
        // above(): tela principal deste ponto
        const LayerPixel mainPx=compose(trueHires?(int)ox:(int)lx,sy,false,trueHires,sprites,bgTiles);
        bool be;if(mainPx.source<=3)be=(cgadsub&(1u<<mainPx.source))!=0;else if(mainPx.source==4)be=(cgadsub&0x10u)&&mainPx.objPal>=4;else be=(cgadsub&0x20u)!=0;
        st.aboveColor=mainPx.c15;
        const bool cw=layerWindow(5,(int)lx);
        if(regionMatch((cgwsel>>4)&3u,cw))be=false;          // janela de cor: "prevent math"
        st.belowEn=be;st.aboveEn=!regionMatch((cgwsel>>6)&3u,cw); // janela de cor: "clip to black"
        if(!st.belowEn)out=st.aboveEn?st.aboveColor:0;
        else{
          const bool addSub=(cgwsel&0x02u)!=0;
          if(addSub&&st.transparent){st.blendMode=false;st.colorHalve=false;}
          else{st.blendMode=addSub;st.colorHalve=(cgadsub&0x40u)&&st.aboveEn;}
          out=blend15(st.aboveEn?st.aboveColor:0,st.blendMode?st.belowColor:fix,colorSub,st.colorHalve);
        }
      }
      fb[rowBase+ox]=rgba15(out);
    }
  }
`;
function attachRev205Hires(files){
  let t=files['src/runtime.hpp'];
  if(!t||t.includes('renderHiresMathSegment('))return files;
  const rep=(from,to,label)=>{if(t.split(from).length!==2)throw new Error('REV205 hires anchor absent/duplicated: '+label);t=t.replace(from,()=>to);};
  rep('  void renderOutputSegment(std::vector<std::uint32_t>&fb,int y,unsigned x0,unsigned x1,',
      FORJA65_REV205_HIRES+'  void renderOutputSegment(std::vector<std::uint32_t>&fb,int y,unsigned x0,unsigned x1,','methods');
  rep('    if(mode==5||mode==6){for(unsigned x=x0;x<x1;x++)',
      '    if(!hiresMathLegacy()&&(mode==5||mode==6||pseudoHires())){renderHiresMathSegment(fb,(mode==5||mode==6)?sy:y,x0,x1,(std::size_t)row*ow,mode==5||mode==6,sprites,&bgTiles);return;}\n'+
      '    if(mode==5||mode==6){for(unsigned x=x0;x<x1;x++)','hook');
  files['src/runtime.hpp']=t;
  return files;
}

// ---------------- REV205: temporizacao do motor de DMA (HDMA) e do entrelacado como no bsnes/ares ----------------
// Medido contra o bsnes: com o inicio do HDMA no ciclo de CPU certo, a espera do divisor de 8 clocks, a devolucao do
// ciclo interrompido, a preparacao do quadro em V=0 e o entrelacado capturado no inicio do quadro, um jogo inteiro
// de codigo aberto (Monster Farm Jump, PeterLemon) roda ciclo a ciclo igual ao bsnes por milhoes de instrucoes.
// FORJA65_HDMA_TIMING=legacy e FORJA65_INTERLACE_LATCH=legacy voltam ao modelo da REV204.
